-- A student belongs to one festival team. Capacity is configured before placement.
alter table public.teams
  add column member_capacity integer not null default 0
  check (member_capacity between 0 and 2000);

create unique index team_members_one_team_per_user_idx
  on public.team_members(user_id);

create or replace function private.prevent_team_over_capacity()
returns trigger
language plpgsql
set search_path = ''
as $$
declare
  target_capacity integer;
begin
  select member_capacity into target_capacity
  from public.teams
  where id = new.team_id
  for update;

  if target_capacity is null or target_capacity = 0 then
    raise exception 'Set this team''s capacity before assigning students';
  end if;

  if (select count(*) from public.team_members where team_id = new.team_id) >= target_capacity then
    raise exception 'This team is already full';
  end if;
  return new;
end;
$$;

create trigger team_members_prevent_over_capacity
before insert on public.team_members
for each row execute function private.prevent_team_over_capacity();

create or replace function public.assign_unassigned_students_to_teams(target_festival_id bigint)
returns table(assigned_count integer, unassigned_count integer)
language plpgsql
security definer
set search_path = ''
as $$
declare
  candidate record;
  target_team_id bigint;
  assigned integer := 0;
  remaining integer := 0;
begin
  if (select auth.uid()) is null
     or not (select private.has_festival_role(target_festival_id, array['owner', 'admin'])) then
    raise exception 'Only festival administrators can assign teams';
  end if;

  perform pg_advisory_xact_lock(81473, target_festival_id::integer);

  if not exists (
    select 1 from public.teams
    where festival_id = target_festival_id and member_capacity > 0
  ) then
    raise exception 'Set a capacity for at least one team before automatic assignment';
  end if;

  for candidate in
    select fm.user_id, left(coalesce(p.student_number, ''), 1) as grade
    from public.festival_members fm
    join public.profiles p on p.id = fm.user_id
    where fm.festival_id = target_festival_id
      and p.account_type = 'student'
      and p.student_number ~ '^[1-9][0-9]{3}$'
      and not exists (select 1 from public.team_members tm where tm.user_id = fm.user_id)
    order by left(p.student_number, 1), random()
  loop
    select t.id into target_team_id
    from public.teams t
    left join public.team_members tm on tm.team_id = t.id
    where t.festival_id = target_festival_id
    group by t.id, t.member_capacity
    having count(tm.user_id) < t.member_capacity
    order by count(tm.user_id), random()
    limit 1;

    if target_team_id is null then
      exit;
    end if;

    insert into public.team_members (team_id, user_id)
    values (target_team_id, candidate.user_id);
    assigned := assigned + 1;
  end loop;

  select count(*) into remaining
  from public.festival_members fm
  join public.profiles p on p.id = fm.user_id
  where fm.festival_id = target_festival_id
    and p.account_type = 'student'
    and p.student_number ~ '^[1-9][0-9]{3}$'
    and not exists (select 1 from public.team_members tm where tm.user_id = fm.user_id);

  return query select assigned, remaining;
end;
$$;

revoke all on function public.assign_unassigned_students_to_teams(bigint) from public, anon;
grant execute on function public.assign_unassigned_students_to_teams(bigint) to authenticated;

-- ============================================================
-- Migration: 20260925080000_fix_booth_rls_recursion.sql
-- ============================================================

-- booths_manager_update (and the equivalent operator checks on inventory_items /
-- queue_entries) inlined a raw `exists (select 1 from booth_members ...)` check.
-- booth_members' own read policy queries booths back, so evaluating the booths
-- policy re-entered booths' RLS mid-evaluation, which Postgres reports as
-- "infinite recursion detected in policy for relation \"booths\"" and surfaces
-- as a 500 on any booths/inventory_items/queue_entries write by a booth
-- operator (or by an owner/admin, since the operator branch is still planned
-- even when the role branch alone would pass).
--
-- Fix: route the booth_members membership check through a security definer
-- function (matching the existing private.has_festival_role /
-- private.can_manage_booth pattern), so it bypasses RLS internally instead of
-- re-entering it.

create or replace function private.is_booth_operator(target_booth_id bigint)
returns boolean language sql stable security definer set search_path = ''
as $$
  select (select auth.uid()) is not null and exists (
    select 1 from public.booth_members
    where booth_id = target_booth_id and user_id = (select auth.uid())
  );
$$;
revoke all on function private.is_booth_operator(bigint) from public, anon;
grant execute on function private.is_booth_operator(bigint) to authenticated;

drop policy booths_manager_update on public.booths;
create policy booths_manager_update on public.booths for update to authenticated
using (
  (select private.has_festival_role(festival_id, array['owner','admin','staff']))
  or (select private.is_booth_operator(id))
)
with check (
  (select private.has_festival_role(festival_id, array['owner','admin','staff']))
  or (select private.is_booth_operator(id))
);

drop policy inventory_read on public.inventory_items;
create policy inventory_read on public.inventory_items for select to authenticated using (
  exists (
    select 1 from public.booths b
    where b.id = inventory_items.booth_id
      and (
        (select private.has_festival_role(b.festival_id, array['owner','admin','staff']))
        or (select private.is_booth_operator(b.id))
      )
  )
);

drop policy inventory_insert on public.inventory_items;
create policy inventory_insert on public.inventory_items for insert to authenticated with check (
  exists (
    select 1 from public.booths b
    where b.id = inventory_items.booth_id
      and (
        (select private.has_festival_role(b.festival_id, array['owner','admin']))
        or (select private.is_booth_operator(b.id))
      )
  )
);

drop policy inventory_update on public.inventory_items;
create policy inventory_update on public.inventory_items for update to authenticated
using (
  exists (
    select 1 from public.booths b
    where b.id = inventory_items.booth_id
      and (
        (select private.has_festival_role(b.festival_id, array['owner','admin']))
        or (select private.is_booth_operator(b.id))
      )
  )
)
with check (
  exists (
    select 1 from public.booths b
    where b.id = inventory_items.booth_id
      and (
        (select private.has_festival_role(b.festival_id, array['owner','admin']))
        or (select private.is_booth_operator(b.id))
      )
  )
);

drop policy inventory_delete on public.inventory_items;
create policy inventory_delete on public.inventory_items for delete to authenticated using (
  exists (
    select 1 from public.booths b
    where b.id = inventory_items.booth_id
      and (
        (select private.has_festival_role(b.festival_id, array['owner','admin']))
        or (select private.is_booth_operator(b.id))
      )
  )
);

drop policy queue_entries_read on public.queue_entries;
create policy queue_entries_read on public.queue_entries for select to authenticated using (
  user_id = (select auth.uid())
  or exists (
    select 1 from public.booths b
    where b.id = queue_entries.booth_id
      and (
