-- ============================================================
-- Migration: 20260925081500_special_case_staff_student_numbers.sql
-- ============================================================

-- Student numbers 9999 (admin) and 9998 (booth_operator) are reserved staff
-- codes: signing up with one of these grants that role directly instead of
-- the default participant role, and skips participant entirely for that
-- account. Both functions read auth.users.raw_user_meta_data directly
-- (never public.profiles), because on_auth_user_auto_enroll fires before
-- on_auth_user_created alphabetically, so profiles does not exist yet when
-- this trigger chain runs.

create or replace function private.enroll_new_user_in_current_festival()
returns trigger language plpgsql security definer set search_path = '' as $function$
declare
  target_festival_id bigint;
  new_student_number text;
  member_role text;
  extra_role text;
begin
  select id into target_festival_id from public.festivals order by id asc limit 1;
  if target_festival_id is null then return new; end if;

  new_student_number := nullif(trim(new.raw_user_meta_data ->> 'student_number'), '');

  if new_student_number = '9999' then
    member_role := 'admin';
    extra_role := 'admin';
  elsif new_student_number = '9998' then
    member_role := 'booth_operator';
    extra_role := 'booth_operator';
  else
    member_role := 'participant';
    extra_role := null;
  end if;

  insert into public.festival_members(festival_id, user_id, role)
  values (target_festival_id, new.id, member_role)
  on conflict (festival_id, user_id) do update set role = excluded.role where excluded.role <> 'participant';

  if extra_role is not null then
    insert into public.festival_member_roles(festival_id, user_id, role)
    values (target_festival_id, new.id, extra_role)
    on conflict do nothing;
  end if;

  return new;
end;
$function$;

create or replace function private.sync_participant_role()
returns trigger language plpgsql security definer set search_path = '' as $function$
declare
  member_student_number text;
  member_account_type text;
begin
  select nullif(trim(raw_user_meta_data ->> 'student_number'), ''),
         coalesce(raw_user_meta_data ->> 'account_type', 'student')
    into member_student_number, member_account_type
  from auth.users where id = new.user_id;

  if member_student_number in ('9999', '9998') then
    return new;
  end if;

  if member_account_type = 'student' then
    insert into public.festival_member_roles (festival_id, user_id, role)
    values (new.festival_id, new.user_id, 'participant')
    on conflict do nothing;
  end if;
  return new;
end;
$function$;

-- ============================================================
-- Migration: 20260925082000_add_booth_queue_enabled.sql
-- ============================================================

-- join_queue_for_actor already checked target_booth.queue_enabled, but the
-- column was never created, so every queue-join attempt failed with
-- "record \"target_booth\" has no field \"queue_enabled\"". Add the column
-- (defaulting to enabled, so existing booths keep working) instead of
-- removing the intended check, since booth operators being able to pause
-- queueing independently of the booth's open/paused/closed status is useful.

alter table public.booths
  add column queue_enabled boolean not null default true;

-- ============================================================
-- Migration: 20260925083000_add_booth_session_throughput.sql
-- ============================================================

-- Replace manually-typed estimated_wait_minutes with the inputs needed to
-- derive it live from the actual queue: how long one turn/session takes
-- (a party doing 인생네컷 together is one session, not one per person) and
-- how many sessions the booth can run at once (e.g. two photo booths running
-- in parallel). The frontend computes ceil(waiting_parties / concurrent_capacity)
-- * session_minutes at read time instead of trusting a stale stored number.

alter table public.booths
  add column session_minutes integer not null default 5 check (session_minutes between 1 and 240),
  add column concurrent_capacity integer not null default 1 check (concurrent_capacity between 1 and 50);

-- ============================================================
-- Migration: 20260925084000_add_queue_companion_student_numbers.sql
-- ============================================================

-- Let a student register who they're queuing with by student number,
-- instead of just a headcount. party_size is now derived server-side from
-- 1 (self) + the companion list, so the two can never disagree.

alter table public.queue_entries
  add column companion_student_numbers text[] not null default '{}';

drop function public.join_queue_for_actor(uuid, bigint, integer);

create function public.join_queue_for_actor(
  actor uuid,
  target_booth_id bigint,
  companion_numbers text[] default '{}'
)
returns queue_entries
language plpgsql
security definer
set search_path = ''
as $function$
declare
  target_booth public.booths%rowtype;
  next_number integer;
  computed_party_size integer;
  result public.queue_entries;
begin
  if actor is null then
    raise exception 'Authentication required';
  end if;
  computed_party_size := 1 + coalesce(array_length(companion_numbers, 1), 0);
  if computed_party_size not between 1 and 20 then
    raise exception 'Party size must be between 1 and 20';
  end if;
  select * into target_booth from public.booths where id = target_booth_id for share;
  if not found or target_booth.status <> 'open' or not target_booth.queue_enabled then
    raise exception 'Queue is not available';
  end if;
  if exists (
    select 1 from public.queue_entries
    where booth_id = target_booth_id and user_id = actor and status in ('waiting', 'called')
  ) then
    raise exception 'Already in queue';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(target_booth_id);
  select coalesce(max(queue_number), 0) + 1 into next_number
  from public.queue_entries where booth_id = target_booth_id;
  insert into public.queue_entries(booth_id, user_id, party_size, queue_number, companion_student_numbers)
  values (target_booth_id, actor, computed_party_size, next_number, companion_numbers)
  returning * into result;
  return result;
end;
$function$;

revoke all on function public.join_queue_for_actor(uuid, bigint, text[]) from public, anon, authenticated;
grant execute on function public.join_queue_for_actor(uuid, bigint, text[]) to service_role;

-- ============================================================
-- Migration: 20260925084500_add_queue_party_members.sql
-- ============================================================

-- A companion's student number now must resolve to a real registered
-- account, and that account gets its own queue_entries row (so it shows in
-- their own reservations) instead of just being recorded as text on the
-- leader's row. party_leader_id groups the leader + companion rows into one
-- party: null on the leader/solo row, set to the leader's id on companion
-- rows. Operators act on the whole party via party_leader_id; each member
-- sees their own row in "내 예약". 9999/9998 (the reserved staff student
-- numbers) can't be added as companions.

alter table public.queue_entries
  add column party_leader_id bigint references public.queue_entries(id) on delete cascade;

create index queue_entries_party_leader_idx on public.queue_entries(party_leader_id);

-- Any authenticated user may check whether a student number belongs to a
-- registered account, returning only what's needed to confirm a companion
-- (not the full profile, which profiles_read otherwise keeps private).
create or replace function public.lookup_student_by_number(target_student_number text)
returns table(user_id uuid, display_name text)
language sql
stable
security definer
set search_path = ''
as $$
  select id, display_name from public.profiles
  where student_number = target_student_number
  limit 1;
$$;
revoke all on function public.lookup_student_by_number(text) from public, anon;
grant execute on function public.lookup_student_by_number(text) to authenticated;

drop function public.join_queue_for_actor(uuid, bigint, text[]);

create function public.join_queue_for_actor(
  actor uuid,
  target_booth_id bigint,
  companion_numbers text[] default '{}'
)
returns queue_entries
language plpgsql
security definer
set search_path = ''
as $function$
declare
  target_booth public.booths%rowtype;
  next_number integer;
  computed_party_size integer;
  result public.queue_entries;
  companion_number text;
  companion_id uuid;
  companion_ids uuid[] := '{}';
  missing_numbers text[] := '{}';
begin
  if actor is null then
    raise exception 'Authentication required';
  end if;
  computed_party_size := 1 + coalesce(array_length(companion_numbers, 1), 0);
  if computed_party_size not between 1 and 20 then
    raise exception 'Party size must be between 1 and 20';
  end if;

  foreach companion_number in array coalesce(companion_numbers, '{}') loop
    if companion_number in ('9999', '9998') then
      raise exception 'Reserved student numbers cannot be added as companions';
    end if;
    select id into companion_id from public.profiles where student_number = companion_number limit 1;
    if companion_id is null then
      missing_numbers := array_append(missing_numbers, companion_number);
    elsif companion_id = actor then
      raise exception 'Cannot add yourself as a companion';
    else
      companion_ids := array_append(companion_ids, companion_id);
    end if;
  end loop;
  if array_length(missing_numbers, 1) is not null then
    raise exception 'Unknown student numbers: %', array_to_string(missing_numbers, ', ');
  end if;

  select * into target_booth from public.booths where id = target_booth_id for share;
  if not found or target_booth.status <> 'open' or not target_booth.queue_enabled then
    raise exception 'Queue is not available';
  end if;
  if exists (
    select 1 from public.queue_entries
    where booth_id = target_booth_id and status in ('waiting', 'called')
      and (user_id = actor or user_id = any(companion_ids))
  ) then
    raise exception 'Already in queue';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(target_booth_id);
  select coalesce(max(queue_number), 0) + 1 into next_number
  from public.queue_entries where booth_id = target_booth_id;

  insert into public.queue_entries(booth_id, user_id, party_size, queue_number, companion_student_numbers)
  values (target_booth_id, actor, computed_party_size, next_number, companion_numbers)
  returning * into result;

  foreach companion_id in array companion_ids loop
    insert into public.queue_entries(booth_id, user_id, party_size, queue_number, party_leader_id)
    values (target_booth_id, companion_id, computed_party_size, next_number, result.id);
  end loop;

  return result;
end;
$function$;

revoke all on function public.join_queue_for_actor(uuid, bigint, text[]) from public, anon, authenticated;
grant execute on function public.join_queue_for_actor(uuid, bigint, text[]) to service_role;

-- ============================================================
-- Migration: 20260925085000_fix_announcements_read_policy_blocking_admin_updates.sql
-- ============================================================

-- Postgres RLS ANDs every applicable SELECT policy into an UPDATE/DELETE's
-- row-visibility check for the same role, on top of the UPDATE policy's own
-- USING/WITH CHECK. announcements_public_read applied to `authenticated`
-- too but required is_published = true with no admin bypass, so it silently
-- combined with announcements_admin_update's check and made it impossible
-- for an admin to ever set is_published to false (or resolve/edit an
-- unpublished-looking row) — "new row violates row-level security policy
-- for table announcements" on every unpublish. Every other public-read
-- policy in this schema already ORs in has_festival_role(...) for exactly
-- this reason (see booths_public_read, categories_public_read, etc.);
-- announcements was the one table missing it.

drop policy announcements_public_read on public.announcements;
create policy announcements_public_read on public.announcements for select to anon, authenticated using (
  (is_published and (expires_at is null or expires_at > now()))
  or (select private.has_festival_role(festival_id, array['owner','admin','staff']))
);

